353	    /// Set the endpoint of the peer
354	    ///
355	    /// # Arguments
356	    ///
357	    /// - `endpoint`, socket address converted to bind endpoint
358	    ///
359	    /// # Note
360	    ///
361	    /// This API still permits support for the "sticky socket" behavior,
362	    /// as sockets should be "unsticked" when manually updating the endpoint
363	    pub fn set_endpoint(&self, endpoint: E) {
364	        log::trace!("peer.set_endpoint");
365	        *self.peer.endpoint.lock() = Some(endpoint);
366	    }
367	
368	    pub fn opaque(&self) -> &C::Opaque {
369	        &self.opaque
370	    }
371	
372	    /// Returns the current endpoint of the peer (for configuration)
373	    ///
374	    /// # Note
375	    ///
376	    /// Does not convey potential "sticky socket" information
377	    pub fn get_endpoint(&self) -> Option<SocketAddr> {
378	        log::trace!("peer.get_endpoint");
379	        self.peer.endpoint.lock().as_ref().map(|e| e.into_address())
380	    }
