1	use arraydeque::ArrayDeque;
2	use spin::Mutex;
3	
4	use core::mem;
5	use core::sync::atomic::{AtomicUsize, Ordering};
6	
7	use super::constants::INORDER_QUEUE_SIZE;
8	
9	pub trait SequentialJob {
10	    fn is_ready(&self) -> bool;
11	
12	    fn sequential_work(self);
13	}
14	
15	pub trait ParallelJob: Sized + SequentialJob {
16	    fn queue(&self) -> &Queue<Self>;
17	
18	    fn parallel_work(&self);
19	}
20	
21	pub struct Queue<J: SequentialJob> {
22	    contenders: AtomicUsize,
23	    queue: Mutex<ArrayDeque<[J; INORDER_QUEUE_SIZE]>>,
24	
25	    #[cfg(debug)]
26	    _flag: Mutex<()>,
27	}
28	
29	impl<J: SequentialJob> Queue<J> {
30	    pub fn new() -> Queue<J> {
31	        Queue {
32	            contenders: AtomicUsize::new(0),
33	            queue: Mutex::new(ArrayDeque::new()),
34	
35	            #[cfg(debug)]
36	            _flag: Mutex::new(()),
37	        }
38	    }
39	
40	    pub fn push(&self, job: J) -> bool {
41	        self.queue.lock().push_back(job).is_ok()
42	    }
43	
44	    pub fn consume(&self) {
45	        // check if we are the first contender
46	        let pos = self.contenders.fetch_add(1, Ordering::SeqCst);
47	        if pos > 0 {
48	            assert!(usize::max_value() > pos, "contenders overflow");
49	            return;
50	        }
51	
52	        // enter the critical section
53	        let mut contenders = 1; // myself
54	        while contenders > 0 {
55	            // check soundness in debug builds
56	            #[cfg(debug)]
57	            let _flag = self
58	                ._flag
59	                .try_lock()
60	                .expect("contenders should ensure mutual exclusion");
61	
62	            // handle every ready element
63	            loop {
64	                let mut queue = self.queue.lock();
65	
66	                // check if front job is ready
67	                match queue.front() {
68	                    None => break,
69	                    Some(job) => {
70	                        if !job.is_ready() {
71	                            break;
72	                        }
73	                    }
74	                };
75	
76	                // take the job out of the queue
77	                let job = queue.pop_front().unwrap();
78	                debug_assert!(job.is_ready());
79	                mem::drop(queue);
80	
81	                // process element
82	                job.sequential_work();
83	            }
84	
85	            #[cfg(debug)]
86	            mem::drop(_flag);
87	
88	            // decrease contenders
89	            contenders = self.contenders.fetch_sub(contenders, Ordering::SeqCst) - contenders;
90	        }
91	    }
92	}
