99	
100	    use std::sync::Arc;
101	    use std::time::Duration;
102	
103	    use rand::thread_rng;
104	    use rand::Rng;
105	
106	    #[test]
107	    fn test_consume_queue() {
108	        struct TestJob {
109	            cnt: Arc<AtomicUsize>,
110	            wait_sequential: Duration,
111	        }
112	
113	        impl SequentialJob for TestJob {
114	            fn is_ready(&self) -> bool {
115	                true
116	            }
117	
118	            fn sequential_work(self) {
119	                thread::sleep(self.wait_sequential);
120	                self.cnt.fetch_add(1, Ordering::SeqCst);
121	            }
122	        }
123	
124	        fn hammer(queue: &Arc<Queue<TestJob>>, cnt: Arc<AtomicUsize>) -> usize {
125	            let mut jobs = 0;
126	            let mut rng = thread_rng();
127	            for _ in 0..10_000 {
128	                if rng.gen() {
129	                    let wait_sequential: u64 = rng.gen();
